const sel=(id,key,opts,cur,extra)=>`<select class="in" id="${id}" data-c="${key}" style="width:auto;max-width:100%"${extra||''}>${opts.map(o=>`<option value="${esc(o[0])}"${String(cur??'')===String(o[0])?' selected':''}>${esc(o[1])}</option>`).join('')}</select>`;
