const fsize=b=>b<1024?b+' B':b<1048576?(b/1024).toFixed(0)+' KB':(b/1048576).toFixed(2)+' MB';
const rnd=n=>{let s='';const a='abcdefghijkmnpqrstuvwxyz23456789';for(let i=0;i<n;i++)s+=a[Math.floor(Math.random()*a.length)];return s};
const hsh=s=>{let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return ('0000000'+(h>>>0).toString(16)).slice(-8)};
const copyBox=(title,text,note)=>openModal(title,`<div style="display:flex;flex-direction:column;gap:10px">${note?`<p class="muted">${note}</p>`:''}<textarea class="in mono" id="csvt" rows="10" readonly>${esc(text)}</textarea></div>`,'<button class="btn" data-a="closeM">Cerrar</button><button class="btn p" data-a="copyCsv">Copiar</button>',true);
