const EV={'employee.hired':'Se registra un ingreso','employee.updated':'Cambia un dato laboral (puesto, sede, jefe, sueldo…)','employee.terminated':'Se registra un cese','leave.approved':'Se aprueba una vacación o permiso','leave.cancelled':'Se anula una vacación o permiso','overtime.approved':'Se aprueban horas extra','payroll.closed':'Se cierra una planilla','candidate.hired':'Se contrata a un candidato','expense.submitted':'Se envía un gasto a aprobación','expense.approved':'Se aprueba un gasto','expense.paid':'Se paga un gasto','course.completed':'Se completa un curso','document.signed':'Se firma un documento','ticket.created':'Se crea una solicitud a RRHH','recognition.given':'Se entrega un reconocimiento','sst.reported':'Se reporta un accidente o incidente','discipline.applied':'Se aplica una medida disciplinaria'};
const evLbl=e=>EV[e]||('Evento «'+e+'»');
const evList=()=>{const s=Object.keys(EV);Object.keys((session&&!session.saas&&T().pl_evSeen)||{}).forEach(e=>{if(!s.includes(e))s.push(e)});return s};
const NK={inicio:['▶','Inicio'],condicion:['?','Condición'],aprobacion:['✓','Aprobación'],accion:['⚙','Acción'],notificacion:['✉','Notificación'],espera:['⏱','Espera'],fin:['■','Fin']};
const CF={area:'Área o unidad',sede:'Sede',empresa:'Empresa',puesto:'Puesto',modalidad:'Modalidad',tipoTrabajador:'Tipo de trabajador',contratoTipo:'Tipo de contrato'};
const NT={aprob:'Solicitudes y aprobaciones',tarea:'Tareas asignadas',equipo:'Movimientos de mi equipo',nomina:'Nómina y pagos',auto:'Avisos de automatizaciones',sistema:'Avisos de la plataforma'};
const CH=[['app','Aplicación'],['correo','Correo'],['push','Push'],['wa','WhatsApp']];
const DEST=[['@colab','El colaborador del evento'],['@jefe','Su jefe directo'],['@rrhh','Recursos Humanos'],['@admin','Administrador de la organización']];
const TEST=['Por hacer','En curso','Hecha'],TPRI={Alta:'crit',Media:'warn',Baja:''};
const PROC=['Onboarding','Offboarding','Contratos','Documentos','Nómina','Equipos y accesos','Otro'];

/* ---------- notificaciones ---------- */
function pref(t,uid,tipo){const d={app:true,correo:['aprob','tarea','sistema'].includes(tipo),push:false,wa:false},p=((t.pl_prefs||{})[uid]||{})[tipo];return p?{...d,...p}:d}
const canalOn=(t,k)=>k!=='wa'||((t.pl_conectores||{}).whatsapp||{}).estado==='Conectado';
function notify(uid,tipo,titulo,texto,ruta,t){t=t||T();const u=t.usuarios.find(x=>x.id===uid);if(!u||!u.activo)return;const p=pref(t,uid,tipo);
 if(p.app)t.pl_notifs.unshift({id:nid('pln'),uid,ts:now(),tipo,titulo,texto:texto||'',ruta:ruta||'',leida:false});
 CH.slice(1).forEach(c=>{if(p[c[0]]&&canalOn(t,c[0]))t.pl_envios.unshift({id:nid('ple'),ts:now(),canal:c[1],para:u.nombre+(c[0]==='correo'?' · '+u.correo:''),asunto:titulo})});
 cap(t.pl_notifs,400);cap(t.pl_envios,300)}
const misNotifs=()=>C('pl_notifs').filter(n=>n.uid===me().id);
const nUnread=()=>misNotifs().filter(n=>!n.leida).length;
const bell=()=>{const n=nUnread();return `<button class="btn" data-a="pl_go" data-r="pl_notif" aria-label="Notificaciones">Avisos${n?` <span class="pill acc" style="padding:0 7px">${n}</span>`:''}</button>`};

/* ---------- eventos del bus: notificaciones, webhooks y workflows ---------- */
function relFrom(p){if(!p)return null;if(p.rel&&p.rel.id)return p.rel;const id=p.relId||['solicitud','gasto','ticket','sobre','inscripcion','caso'].map(k=>p[k]&&p[k].relId).find(Boolean)||(p.rec&&p.rec.paraId);return relSafe(id)}
function resolveUser(code,rel){if(code==='@colab')return userOfRel(rel);if(code==='@jefe')return rel&&rel.jefeId?userOfRel(relSafe(rel.jefeId)):null;if(code==='@rrhh')return usersRole('r_rrhh')[0]||usersRole('r_admin')[0]||null;if(code==='@admin')return usersRole('r_admin')[0]||null;const u=usr(code);return u&&u.activo?u:null}
const destLbl=c=>{const d=DEST.find(x=>x[0]===c);return d?d[1][0].toLowerCase()+d[1].slice(1):uName(c)};
function notifyFor(ev,p){const rel=relFrom(p),yo=session.userId,to=(u,...a)=>{if(u&&u.id!==yo)notify(u.id,...a)};
 if(ev==='leave.approved'&&rel)to(userOfRel(rel),'aprob','Aprobaron tu solicitud de '+String(p.tipo||'permiso').toLowerCase(),(p.desde?fd(p.desde)+(p.hasta&&p.hasta!==p.desde?' al '+fd(p.hasta):''):'')+(p.dias?' · '+pl(p.dias,'día'):''),p.tipo==='Vacaciones'?'ti_vacaciones':'ti_ausencias');
 else if(ev==='overtime.approved'&&rel)to(userOfRel(rel),'aprob','Aprobaron tus horas extra','Ya figuran en tu registro de horas extra.','ti_extras');
 else if(ev==='employee.hired'&&rel)to(resolveUser('@jefe',rel),'equipo','Nuevo ingreso en tu equipo: '+nm(rel),((get('puestos',rel.puestoId)||{}).nombre||'')+' · ingresa el '+fd(rel.ingreso),'colaboradores');
 else if(ev==='employee.terminated'&&rel)to(resolveUser('@jefe',rel),'equipo','Cese registrado en tu equipo: '+nm(rel),'Último día: '+fd(rel.cese),'colaboradores');
 else if(ev==='employee.updated'&&rel){if(p.campo==='jefeId')to(resolveUser('@jefe',rel),'equipo',nm(rel)+' ahora reporta a ti','Se registró un cambio de jefe directo.','colaboradores');
  else if(['puestoId','sedeId','modalidad'].includes(p.campo))to(userOfRel(rel),'equipo','Se actualizó tu ficha: '+({puestoId:'puesto',sedeId:'sede',modalidad:'modalidad'})[p.campo],'Revisa el historial de tu ficha.','inicio')}
 else if(ev==='expense.approved'&&rel)to(userOfRel(rel),'aprob','Aprobaron tu gasto','Finanzas programará el reembolso.','op_gastos');
 else if(ev==='expense.paid'&&rel)to(userOfRel(rel),'nomina','Pagaron tu gasto','El reembolso ya fue registrado como pagado.','op_gastos');
 else if(ev==='payroll.closed')[...usersRole('r_rrhh'),...usersRole('r_admin')].forEach(u=>to(u,'nomina','Se cerró la planilla '+(p.periodo||''),'Ya se pueden publicar las boletas.','no_periodos'))}
function payloadOf(ev,p,rel){const d={};if(rel){d.employee_id=rel.id;d.employee_code=rel.codigo}if(p){['campo','tipo','desde','hasta','dias','periodo','motivo'].forEach(k=>{if(p[k]!=null&&typeof p[k]!=='object')d[k]=p[k]})}
 return JSON.stringify({id:'evt_'+rnd(10),event:ev,occurred_at:now(),organization:session.tenantId,data:d})}
function deliver(wh,ev,body,retryOf){const t=T(),fail=!!wh.simFalla;
 if(retryOf){retryOf.intentos++;retryOf.ts=now();retryOf.estado=fail?'Fallido':'Entregado';retryOf.codigo=fail?'Sin respuesta (tiempo agotado)':'200 OK';tlog(fail?'error':'info','Webhooks',(fail?'Reintento fallido':'Reintento entregado')+' · '+ev+' → '+wh.url);return retryOf}
 const e={id:nid('pld'),whId:wh.id,url:wh.url,ts:now(),evento:ev,estado:fail?'Fallido':'Entregado',codigo:fail?'Sin respuesta (tiempo agotado)':'200 OK',intentos:1,cuerpo:body,firma:'sha256='+hsh(wh.secreto+body)+hsh(body+wh.secreto)};
 t.pl_entregas.unshift(e);cap(t.pl_entregas,200);tlog(fail?'error':'info','Webhooks',(fail?'Entrega fallida':'Entrega correcta')+' · '+ev+' → '+wh.url);return e}
on('*',(ev,p)=>{if(!session||session.saas)return;const t=db.data[session.tenantId];if(!t||!t.pl_cfg)return;
 try{t.pl_evSeen[ev]=(t.pl_evSeen[ev]||0)+1;const rel=relFrom(p);
  notifyFor(ev,p);
  t.pl_webhooks.filter(w=>w.activo&&(w.eventos.includes(ev)||w.eventos.includes('*'))).forEach(w=>deliver(w,ev,payloadOf(ev,p,rel)));
  if(modOn('automatizacion'))t.pl_workflows.filter(w=>w.activo&&!w.borrado&&w.trigger===ev).forEach(w=>wfStart(w,ev,rel));
  PC=null}catch(e){console.error(e);try{tlog('error','Bus de eventos','Fallo al procesar '+ev+': '+e.message,t)}catch(x){}}});

/* ---------- motor de workflows ---------- */
const areaChain=rel=>{const a=[];let u=uniOf(rel),n=0;while(u&&n++<30){a.push(u.id);u=u.padreId?get('unidades',u.padreId):null}return a};
const condVals=(rel,c)=>c==='area'?areaChain(rel):c==='sede'?[rel.sedeId]:c==='empresa'?[rel.empresaId]:c==='puesto'?[rel.puestoId]:[rel[c]];
const condOpts=c=>c==='area'?opt('unidades'):c==='sede'?opt('sedes'):c==='empresa'?opt('empresas'):c==='puesto'?opt('puestos'):lista(c==='modalidad'?'modalidad':c==='tipoTrabajador'?'tipoTrabajador':'contratoTipo').map(x=>[x,x]);
const condValLbl=(c,v)=>{const col={area:'unidades',sede:'sedes',empresa:'empresas',puesto:'puestos'}[c];return col?((T()[col].find(x=>x.id===v)||{}).nombre||'(eliminado)'):v};
const condLabel=n=>{const c=n.cfg||{};return (CF[c.campo]||'Campo')+' '+(c.op==='no'?'no es':'es')+' '+condValLbl(c.campo,c.valor)};
const condOk=(n,rel)=>{const c=n.cfg,hit=condVals(rel,c.campo).includes(c.valor);return c.op==='no'?!hit:hit};
const tpl=(s,rel)=>String(s||'').replace(/\{(colaborador|puesto|area|sede|empresa|jefe)\}/g,(m,k)=>!rel?'—':k==='colaborador'?nm(rel):k==='puesto'?(get('puestos',rel.puestoId)||{}).nombre||'':k==='area'?(uniOf(rel)||{}).nombre||'':k==='sede'?(get('sedes',rel.sedeId)||{}).nombre||'':k==='empresa'?(get('empresas',rel.empresaId)||{}).nombre||'':rel.jefeId?relName(rel.jefeId):'sin jefe');
