/* ---------- pendientes, delegación y acciones en nombre de otro ---------- */
let PC=null,IMPS=null,BULK=false;
const delegAct=d=>d.activo&&d.desde<=TODAY&&d.hasta>=TODAY;
function withUser(uid,fn){const prev=session.userId;session.userId=uid;try{return fn()}finally{session.userId=prev}}
function allPend(){if(PC)return PC;let a=[];try{a=pendientes().map(p=>({...p,deleg:''}))}catch(e){console.error(e)}
 const yo=me().id,seen=new Set(a.map(p=>p.mod+'|'+p.id));
 const mio=myRel();
 C('pl_deleg').filter(d=>d.aUid===yo&&delegAct(d)&&usr(d.deUid)&&usr(d.deUid).activo).forEach(d=>{try{withUser(d.deUid,pendientes).forEach(p=>{const k=p.mod+'|'+p.id;if(!seen.has(k)&&!(mio&&p.relId===mio.id)){seen.add(k);a.push({...p,deleg:d.deUid})}})}catch(e){console.error(e)}});
 a.forEach(p=>p.key=p.mod+'|'+p.id);PC=a;Promise.resolve().then(()=>{PC=null});return a}
function actAs(uid,fn){const prev=session.userId;if(!uid||uid===prev){fn();return}
 session.userId=uid;IMPS={prev};try{fn()}catch(e){console.error(e)}
 if(BULK)return;if(!$('modal').innerHTML)finImp()}
function finImp(){if(!IMPS)return;session.userId=IMPS.prev;IMPS=null;PC=null;save();render()}
new MutationObserver(()=>{if(IMPS&&!BULK&&!$('modal').innerHTML)finImp()}).observe(document.getElementById('modal'),{childList:true});
function runPend(p,kind){const a=p[kind];if(!a||!A[a.a])return toast('Esta acción ya no está disponible');
 if(p.deleg)log(kind==='aprobar'?'Aprobación por delegación':'Resolución por delegación','Pendientes',p.t,p.relId||'','En nombre de '+uName(p.deleg),p.tipo);
 PC=null;actAs(p.deleg,()=>A[a.a]({id:a.id},{target:document.body}))}
const pendTask=()=>C('pl_tareas').filter(k=>!k.borrado&&k.respId===me().id&&k.estado!=='Hecha').map(k=>({id:k.id,tipo:'Tarea de RRHH',t:k.titulo,d:(k.vence<TODAY?'Venció el ':'Vence el ')+fd(k.vence)+' · prioridad '+k.prioridad.toLowerCase()+(k.relId&&relSafe(k.relId)?' · '+relName(k.relId):''),relId:k.relId,abrir:{r:'pl_tareas'},hacer:{a:'pl_tDone',id:k.id,l:'Marcar hecha'}}));
const pendAp=()=>C('pl_aprobs').filter(a=>apCan(a,me().id)).map(a=>({id:a.id,tipo:a.tipo,t:a.titulo,d:(a.modo==='Paralelo'?'Aprobación en paralelo':'Nivel '+(a.nivel+1)+' de '+a.niveles.length)+' · solicitado por '+a.por+(a.detalle?' · '+a.detalle:''),relId:a.relId,aprobar:{a:'pl_apOk',id:a.id},rechazar:{a:'pl_apNo',id:a.id},abrir:{r:'pl_aprob'}}));

function vPend(){const tab=ui.pl_pTab||'bandeja',all=allPend(),q=norm(ui.pl_pq),misD=C('pl_deleg').filter(d=>d.deUid===me().id||d.aUid===me().id||can('plataforma.config.administrar'));
 const head=pageHead('Mi trabajo','Pendientes',bell()+(can('plataforma.delegar')?'<button class="btn" data-a="pl_dgNew">Delegar mis aprobaciones</button>':''),all.length?`Tienes <b>${pl(all.length,'pendiente')}</b>${all.filter(p=>p.aprobar).length?', '+all.filter(p=>p.aprobar).length+' por aprobar':''}.`:'');
 let body='';
 if(tab==='bandeja'){const tipos=[...new Set(all.map(p=>p.tipo))].sort((a,b)=>a.localeCompare(b,'es'));if(ui.pl_pTipo&&!tipos.includes(ui.pl_pTipo))ui.pl_pTipo='';
  const rs=all.filter(p=>(!ui.pl_pTipo||p.tipo===ui.pl_pTipo)&&(!ui.pl_pSolo||(ui.pl_pSolo==='apr'?!!p.aprobar:ui.pl_pSolo==='del'?!!p.deleg:!p.aprobar))&&(!q||norm(p.t+' '+p.d+' '+p.tipo).includes(q)));
  const selK=ui.pl_sel||(ui.pl_sel={});Object.keys(selK).forEach(k=>{if(!rs.some(p=>p.key===k&&p.aprobar))delete selK[k]});const nSel=Object.keys(selK).length,mas=flagOn('pendientes.masivo');
  const g={};rs.forEach(p=>(g[p.tipo]=g[p.tipo]||[]).push(p));
  const row=p=>`<div class="pl-it">${mas&&p.aprobar?`<input type="checkbox" class="chk" id="pl_ck_${esc(p.key)}" data-plsel="${esc(p.key)}"${selK[p.key]?' checked':''} aria-label="Seleccionar" style="margin-top:3px">`:mas?'<span style="width:16px;flex:none"></span>':''}
   <div class="g"><b>${esc(p.t)}</b><div class="muted">${esc(p.d||'')}</div>${p.deleg?`<div style="margin-top:4px">${pill('Delegado por '+uName(p.deleg),'acc')}</div>`:''}</div>
   <div class="row" style="flex:none">${p.aprobar?`<button class="btn s p" data-a="pl_pAct" data-k="${esc(p.key)}" data-x="aprobar">Aprobar</button>`:''}${p.rechazar?`<button class="btn s d" data-a="pl_pAct" data-k="${esc(p.key)}" data-x="rechazar">Rechazar</button>`:''}${p.hacer?`<button class="btn s p" data-a="pl_pAct" data-k="${esc(p.key)}" data-x="hacer">${esc(p.hacer.l)}</button>`:''}${p.abrir?`<button class="btn s" data-a="pl_pOpen" data-k="${esc(p.key)}">Abrir</button>`:''}</div></div>`;
  body=`<div class="ph"><div class="row" style="flex:1">${srch('pl_pq','Buscar en mis pendientes')}${sel('pl_pTipo','pl_pTipo',[['','Todos los tipos'],...tipos.map(t=>[t,t+' — '+all.filter(p=>p.tipo===t).length])],ui.pl_pTipo)}${sel('pl_pSolo','pl_pSolo',[['','Todo'],['apr','Solo por aprobar'],['otr','Solo tareas y avisos'],['del','Solo delegados a mí']],ui.pl_pSolo)}</div></div>
  ${mas&&rs.some(p=>p.aprobar)?`<div class="pl-gh"><span class="muted">${nSel?`<b style="text-transform:none;letter-spacing:0;font-size:13px;color:var(--ink)">${pl(nSel,'seleccionado')}</b>`:'Marca varios pendientes aprobables para resolverlos juntos. Los rechazos se hacen uno por uno porque exigen motivo.'}</span><div class="row">${nSel?'<button class="btn s" data-a="pl_pSelNone">Quitar selección</button><button class="btn s p" data-a="pl_pBulk">Aprobar seleccionados</button>':'<button class="btn s" data-a="pl_pSelAll">Seleccionar todos los aprobables</button>'}</div></div>`:''}
  ${rs.length?Object.keys(g).sort((a,b)=>a.localeCompare(b,'es')).map(k=>`<div class="pl-gh"><b>${esc(k)} — ${g[k].length}</b>${g[k][0].abrir?`<button class="btn s ghost" data-a="pl_pOpen" data-k="${esc(g[k][0].key)}">Ir a la pantalla</button>`:''}</div>${g[k].map(row).join('')}`).join('')
   :all.length?emptyState('Nada coincide con los filtros','Prueba con otra búsqueda o quita los filtros.','<button class="btn" data-a="pl_pClear">Limpiar filtros</button>')
   :emptyState('Estás al día','Aquí se juntan las solicitudes que te toca aprobar, tus tareas y lo que debes firmar o completar en todos los módulos. Cuando alguien de tu equipo pida vacaciones o registre un gasto, aparecerá aquí.',can('plataforma.tareas.ver')?'<button class="btn" data-a="pl_go" data-r="pl_tareas">Ver mis tareas</button>':'')}`}
 else{body=`<div class="pb" style="display:flex;flex-direction:column;gap:12px"><div class="note"><b>Qué cubre la delegación.</b> Mientras dure el rango de fechas, la persona delegada ve en su bandeja los pendientes de quien delega y puede aprobarlos, rechazarlos o completarlos. Cada decisión queda en la auditoría como «por delegación», con el nombre de quien actuó y en nombre de quién. Las solicitudes del propio delegado quedan fuera: nadie aprueba lo suyo por delegación. No transfiere permisos fuera de la bandeja: el delegado no ve pantallas ni datos adicionales, y la delegación termina sola al vencer.</div></div>
  ${misD.length?`<div class="tw"><table><thead><tr><th>Delega</th><th>En</th><th>Desde</th><th>Hasta</th><th>Motivo</th><th>Estado</th><th></th></tr></thead><tbody>${misD.slice().sort((a,b)=>b.desde.localeCompare(a.desde)).map(d=>{const e=!d.activo?['Cancelada','']:d.hasta<TODAY?['Terminada','']:d.desde>TODAY?['Programada','warn']:['Vigente','ok'];return `<tr><td><b>${esc(uName(d.deUid))}</b></td><td>${esc(uName(d.aUid))}</td><td class="num">${fd(d.desde)}</td><td class="num">${fd(d.hasta)}</td><td>${esc(d.motivo||'—')}</td><td>${pill(e[0],e[1])}</td><td style="text-align:right">${d.activo&&d.hasta>=TODAY&&(d.deUid===me().id||can('plataforma.config.administrar'))?`<button class="btn s d" data-a="pl_dgEnd" data-id="${d.id}">Terminar</button>`:''}</td></tr>`}).join('')}</tbody></table></div>`
   :emptyState('Sin delegaciones','Si vas a estar de vacaciones o de licencia, delega tus aprobaciones para que tu equipo no se quede esperando.',can('plataforma.delegar')?'<button class="btn p" data-a="pl_dgNew">Delegar mis aprobaciones</button>':'')}`}
 return head+`<div class="panel">${tabsH('pl_pTab',[['bandeja','Por resolver',all.length],['deleg','Delegaciones',misD.filter(delegAct).length,'acc']],tab)}${body}</div>`}
const pendByKey=k=>allPend().find(p=>p.key===k);

/* ---------- campos personalizados ---------- */
const CFT=['Texto','Número','Fecha','Selector','Multiselección','Casilla','Usuario','Archivo','URL','Moneda','Porcentaje'];
const CFE=['Colaborador','Tarea de RRHH','Empresa','Sede','Unidad','Puesto','Vacante'];
const cfOf=ent=>C('pl_campos').filter(c=>c.activo&&c.entidad===ent);
const cfField=c=>{const b={k:'cf_'+c.id,l:c.nombre+(c.tipo==='Archivo'?' (nombre del archivo, simulado)':c.tipo==='Porcentaje'?' (%)':''),req:c.req?1:0};
 if(c.tipo==='Número'||c.tipo==='Moneda'||c.tipo==='Porcentaje')b.type='number';else if(c.tipo==='Fecha')b.type='date';else if(c.tipo==='Selector')b.opts=c.opciones;else if(c.tipo==='Multiselección'){b.type='checks';b.opts=c.opciones;b.full=1}else if(c.tipo==='Casilla')b.opts=['Sí','No'];else if(c.tipo==='Usuario')b.opts=uOpts();return b};
const cfVals=id=>T().pl_cfVals[id]||{};
const cfInit=(ent,id)=>{const o={},v=cfVals(id);cfOf(ent).forEach(c=>o['cf_'+c.id]=v[c.id]??(c.tipo==='Multiselección'?[]:''));return o};
function cfCheck(ent,o){for(const c of cfOf(ent)){const v=o['cf_'+c.id];if(v===''||v==null)continue;
 if(c.tipo==='URL'&&!/^https?:\/\/[^\s.]+\.[^\s]+$/i.test(v))return '«'+c.nombre+'» debe ser un enlace que empiece con http:// o https://';
 if(c.tipo==='Porcentaje'&&!(Number(v)>=0&&Number(v)<=100))return '«'+c.nombre+'» debe estar entre 0 y 100.'}return ''}
function cfSave(ent,id,o){const cur={...cfVals(id)},ch=[];cfOf(ent).forEach(c=>{let v=o['cf_'+c.id];if(['Número','Moneda','Porcentaje'].includes(c.tipo)&&v!=='')v=Number(v);if(JSON.stringify(cur[c.id]??'')!==JSON.stringify(v??'')){ch.push(c.nombre);cur[c.id]=v}});T().pl_cfVals[id]=cur;return ch}
function cfShow(c,v,moneda){if(v===''||v==null||(Array.isArray(v)&&!v.length))return '<span class="muted">Sin dato</span>';
 if(c.tipo==='Multiselección')return v.map(x=>pill(x)).join(' ');if(c.tipo==='Casilla')return pill(v,v==='Sí'?'ok':'');if(c.tipo==='Usuario')return esc(uName(v));
 if(c.tipo==='URL')return `<a href="${esc(v)}" target="_blank" rel="noopener noreferrer">${esc(v)}</a>`;if(c.tipo==='Fecha')return fd(v);if(c.tipo==='Moneda')return `<span class="num">${money(v,moneda)}</span>`;
 if(c.tipo==='Porcentaje')return `<span class="num">${esc(v)} %</span>`;if(c.tipo==='Archivo')return `<span class="mono">${esc(v)}</span> <span class="muted">(simulado)</span>`;return esc(v)}
function fichaCF(rel){const cs=cfOf('Colaborador'),v=cfVals(rel.id),ed=can('plataforma.campos.valores.editar');
 return `<div class="row" style="justify-content:space-between;margin-bottom:14px"><h3>Campos adicionales de la organización</h3>${ed?`<button class="btn s" data-a="pl_cfEditRel" data-id="${rel.id}">Editar</button>`:''}</div>
 <dl>${cs.map(c=>`<div><dt>${esc(c.nombre)}</dt><dd>${cfShow(c,v[c.id],cur(rel))}</dd>${c.ayuda?`<div class="muted" style="font-size:12px">${esc(c.ayuda)}</div>`:''}</div>`).join('')}</dl>
 <p class="muted" style="margin-top:16px">Estos campos los define tu organización en Centro de configuración › Campos personalizados.</p>`}

