 const head=pageHead('Mi trabajo','Tareas',bell()+(tab?`<button class="btn ${view==='tablero'?'p':''}" data-a="pl_set" data-k="pl_tView" data-v="tablero">Tablero</button><button class="btn ${view==='lista'?'p':''}" data-a="pl_set" data-k="pl_tView" data-v="lista">Lista</button>`:'')+'<button class="btn p" data-a="pl_tNew">Nueva tarea</button>',ges?'Tareas internas de Recursos Humanos: las propias, las del equipo y las que crean las automatizaciones.':'Las tareas que tienes asignadas y las que creaste.');
