function autoMap(def,cols){const m={},used=new Set(),nc=cols.map(norm);
 def.f.forEach(f=>{const i=nc.findIndex((c,k)=>!used.has(k)&&(c===norm(f[1])||f[3].includes(c)));if(i>=0){m[f[0]]=i;used.add(i)}});
 def.f.forEach(f=>{if(m[f[0]]!=null)return;const i=nc.findIndex((c,k)=>!used.has(k)&&c&&f[3].some(s=>c.includes(s)||s.includes(c)));if(i>=0){m[f[0]]=i;used.add(i)}else m[f[0]]=''});return m}
