 pl_segEdit:()=>{const g=cfg().seg,sn=['Sí','No'];openForm(()=>({title:'Política de seguridad',fields:[{k:'minLen',l:'Longitud mínima de la contraseña',type:'number',req:1},{k:'mayus',l:'Exige mayúsculas',opts:sn,req:1,keep:1},{k:'numero',l:'Exige números',opts:sn,req:1,keep:1},{k:'simbolo',l:'Exige símbolos',opts:sn,req:1,keep:1},{k:'caduca',l:'Caducidad en días (0 = no caduca)',type:'number',req:1},{k:'historial',l:'No repetir las últimas (contraseñas)',type:'number',req:1},{k:'mfa',l:'Verificación en dos pasos',opts:['Opcional','Obligatorio para administradores','Obligatorio para todos'],req:1,keep:1,full:1},{k:'inactividad',l:'Cierre por inactividad (minutos)',type:'number',req:1},{k:'sesiones',l:'Sesiones simultáneas por usuario',type:'number',req:1},{k:'intentos',l:'Intentos fallidos antes de bloquear',type:'number',req:1},{k:'bloqueo',l:'Minutos de bloqueo',type:'number',req:1},...(flagOn('acceso.documento')?[{k:'accesoDoc',l:'Ingreso con documento de identidad (personal sin correo)',opts:sn,req:1,keep:1,full:1}]:[])],
  submit:o=>{if(+o.minLen<8||+o.minLen>64)return 'La longitud mínima debe estar entre 8 y 64 caracteres.';if(+o.intentos<3)return 'Permite al menos 3 intentos antes de bloquear.';if(+o.inactividad<5)return 'El cierre por inactividad debe ser de al menos 5 minutos.';if(+o.sesiones<1)return 'Debe permitirse al menos una sesión.';
   const ch=[];Object.keys(g).forEach(k=>{if(o[k]!==undefined){const v=typeof g[k]==='number'?Number(o[k]):o[k];if(v!==g[k]){ch.push(k);g[k]=v}}});if(!ch.length)return 'No hay cambios para guardar.';log('Cambio de política de seguridad','Seguridad',tenant().nombre,'','',ch.length+' ajuste(s): '+ch.join(', '));toast('Política de seguridad guardada')}}),{...g})},
 /* importador */
