 pl_impTpl:()=>{const st=ui.pl_imp;st.raw=IMP[st.tipo].tpl();st.err='';render()},
 pl_impTplCopy:()=>copyBox('Plantilla de '+IMP[ui.pl_imp.tipo].t,IMP[ui.pl_imp.tipo].tpl(),'Copia este contenido, pégalo en Excel o en un archivo .csv, reemplaza las filas de ejemplo con tus datos y vuelve a pegarlo aquí. La plantilla trae una fila con error a propósito, para que veas cómo se informa.'),
 pl_impNext:()=>{const st=ui.pl_imp;st.raw=$('pl_impTxt').value;const rows=parseCsv(st.raw);st.err='';
  if(rows.length<2)st.err='Pega al menos la fila de títulos y una fila de datos.';else if(rows.length>501)st.err='El archivo tiene '+(rows.length-1)+' filas. Importa como máximo 500 por vez.';else if(rows[0].length<2)st.err='Solo se detectó una columna. Revisa que las columnas estén separadas por coma, punto y coma o tabulación.';
  if(st.err)return render();st.cols=rows[0];st.rows=rows.slice(1);st.map=autoMap(IMP[st.tipo],st.cols);st.step=2;render()},
