 pl_impVal:()=>{const st=ui.pl_imp,def=IMP[st.tipo],falt=def.f.filter(f=>f[2]&&(st.map[f[0]]===''||st.map[f[0]]==null)),us=Object.values(st.map).filter(v=>v!==''&&v!=null).map(String);
  if(falt.length){st.err='Falta indicar la columna de: '+falt.map(f=>f[1]).join(', ')+'.';return render()}if(new Set(us).size<us.length){st.err='Una misma columna está asignada a dos datos distintos.';return render()}
  st.err='';st.res=impValidate(st);st.step=3;ui.pl_impV='todas';render()},
 pl_impRun:()=>{const st=ui.pl_imp;st.res=impValidate(st);const ok=st.res.filter(r=>!r.e.length).length,bad=st.res.length-ok;if(!ok){toast('Ya no hay filas válidas: revisa la validación');return render()}
  confirmBox('Importar '+pl(ok,'fila válida','filas válidas'),`Se ${st.tipo==='colab'?'crearán <b>'+pl(ok,'colaborador','colaboradores')+'</b> con su historial de ingreso':st.tipo==='sal'?'actualizará el sueldo de <b>'+pl(ok,'colaborador','colaboradores')+'</b>':'registrará el saldo de <b>'+pl(ok,'colaborador','colaboradores')+'</b>'}.${bad?' Las '+bad+' fila(s) con error no se importan.':''} Queda registrado en la auditoría.`,'Importar',()=>{st.rep=impRun(st);st.step=4;st.raw='';PC=null;toast(st.rep.ok+' fila(s) importadas')})},
