 pl_tkNew:()=>openForm(()=>({title:'Nuevo token de API',ok:'Crear token',note:'Marca solo los alcances que el otro sistema necesita. El valor completo se mostrará una única vez.',fields:[{k:'nombre',l:'Para qué se usará',req:1,full:1},{k:'alcances',l:'Alcances',type:'checks',opts:SCOPES.map(s=>[s[0],s[1]]),req:1,full:1}],
  submit:o=>{if(T().pl_tokens.some(k=>k.estado==='Activo'&&norm(k.nombre)===norm(o.nombre)))return 'Ya hay un token activo con ese nombre.';const sec='gestia_live_'+rnd(32),k={id:nid('plk'),nombre:o.nombre,pref:sec.slice(0,14),fin:sec.slice(-4),alcances:o.alcances,creado:now(),por:me().nombre,ultimo:'',estado:'Activo'};T().pl_tokens.unshift(k);log('Alta','Token de API',k.nombre,k.id,'',o.alcances.join(', '));
   setTimeout(()=>openModal('Copia tu token ahora',`<div style="display:flex;flex-direction:column;gap:10px"><div class="err">Es la única vez que verás el valor completo. Si lo pierdes, revoca este token y crea otro.</div><textarea class="in mono" id="csvt" rows="2" readonly>${sec}</textarea><p class="muted">Token «${esc(k.nombre)}» · alcances: ${o.alcances.map(esc).join(', ')}</p></div>`,'<button class="btn" data-a="closeM">Ya lo guardé</button><button class="btn p" data-a="copyCsv">Copiar</button>'),0)}}),{alcances:[]}),
